"use client";

import React, { useState, useMemo } from "react";
import Link from "next/link";
import {
  CheckCircle2,
  AlertCircle,
  Loader2,
  Calendar,
  Clock,
  Phone,
  User,
  Stethoscope,
  ShieldCheck,
} from "lucide-react";
import { INITIAL_CATEGORIES, INITIAL_SERVICES } from "@/lib/clinic-data";

export interface BookingFormProps {
  initialDirection?: string;
  initialService?: string;
  initialDoctor?: string;
  doctorsList?: { fullName: string; specialization: string }[];
  compact?: boolean;
  onSuccess?: () => void;
}

export function formatRussianPhoneInput(raw: string): string {
  const digits = raw.replace(/\D/g, "");
  if (!digits) return "";

  let normalized = digits;
  if (normalized.startsWith("8")) {
    normalized = "7" + normalized.slice(1);
  } else if (!normalized.startsWith("7")) {
    normalized = "7" + normalized;
  }

  normalized = normalized.slice(0, 11);

  let result = "+7";
  if (normalized.length > 1) {
    result += " (" + normalized.slice(1, 4);
  }
  if (normalized.length >= 5) {
    result += ") " + normalized.slice(4, 7);
  }
  if (normalized.length >= 8) {
    result += "-" + normalized.slice(7, 9);
  }
  if (normalized.length >= 10) {
    result += "-" + normalized.slice(9, 11);
  }
  return result;
}

export default function BookingForm({
  initialDirection = "",
  initialService = "",
  initialDoctor = "",
  doctorsList = [],
  compact = false,
  onSuccess,
}: BookingFormProps) {
  const [patientName, setPatientName] = useState("");
  const [phone, setPhone] = useState("");
  const [direction, setDirection] = useState(initialDirection);
  const [serviceTitle, setServiceTitle] = useState(initialService);
  const [preferredDoctor, setPreferredDoctor] = useState(initialDoctor);
  const [desiredDate, setDesiredDate] = useState("");
  const [desiredTime, setDesiredTime] = useState("");
  const [comment, setComment] = useState("");
  const [consentAccepted, setConsentAccepted] = useState(true);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [submittedData, setSubmittedData] = useState<{
    id: number;
    patientName: string;
  } | null>(null);

  const filteredServices = useMemo(() => {
    if (!direction) return INITIAL_SERVICES;
    const cat = INITIAL_CATEGORIES.find(
      (c) => c.slug === direction || c.title === direction
    );
    if (!cat) return INITIAL_SERVICES;
    return INITIAL_SERVICES.filter((s) => s.categorySlug === cat.slug);
  }, [direction]);

  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val.length < phone.length && val.replace(/\D/g, "").length <= 1) {
      setPhone("");
      return;
    }
    setPhone(formatRussianPhoneInput(val));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    setErrorMessage(null);

    if (patientName.trim().length < 2) {
      setErrorMessage("Пожалуйста, укажите ваше имя (минимум 2 символа).");
      return;
    }

    const digits = phone.replace(/\D/g, "");
    if (digits.length !== 11) {
      setErrorMessage(
        "Пожалуйста, введите полный номер телефона в формате +7 (999) 000-00-00."
      );
      return;
    }

    if (!consentAccepted) {
      setErrorMessage(
        "Необходимо подтвердить согласие на обработку персональных данных."
      );
      return;
    }

    setIsSubmitting(true);
    try {
      const selectedCat = INITIAL_CATEGORIES.find(
        (c) => c.slug === direction || c.title === direction
      );

      const payload = {
        patientName: patientName.trim(),
        phone,
        direction: selectedCat ? selectedCat.title : direction,
        serviceTitle,
        preferredDoctor,
        desiredDate,
        desiredTime,
        comment: comment.trim(),
        consentAccepted,
      };

      // Save to browser localStorage for autonomous demo mode
      let localId = Math.floor(1000 + Math.random() * 9000);
      try {
        const raw = localStorage.getItem("kvalitet_demo_appointments");
        const list = raw ? JSON.parse(raw) : [];
        localId = list.length + 1;
        list.unshift({
          id: localId,
          ...payload,
          status: "new",
          createdAt: new Date().toISOString(),
        });
        localStorage.setItem(
          "kvalitet_demo_appointments",
          JSON.stringify(list)
        );
      } catch {
        // Ignore storage quota errors
      }

      // GitHub Pages is static hosting: keep demo submissions in this browser only.
      setSubmittedData({
        id: localId,
        patientName: payload.patientName,
      });

      if (onSuccess) onSuccess();
    } finally {
      setIsSubmitting(false);
    }
  };

  if (submittedData) {
    return (
      <div
        role="status"
        aria-live="polite"
        className="rounded-2xl border border-[#164E43]/20 bg-[#ECF4F1] p-6 sm:p-8 text-[#14221E]"
      >
        <div className="flex items-start gap-4">
          <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-[#164E43] text-white">
            <CheckCircle2 className="h-6 w-6" />
          </div>
          <div className="space-y-3">
            <span className="inline-flex items-center rounded-full bg-white/80 px-3 py-1 text-xs font-medium text-[#164E43]">
              Демо-режим: заявка №{submittedData.id} принята (без внешней БД)
            </span>
            <h3 className="font-serif-editorial text-2xl font-semibold text-[#14221E]">
              Спасибо, {submittedData.patientName}! Ваша заявка принята
            </h3>
            <p className="text-sm leading-relaxed text-[#525D59]">
              Администратор стоматологической клиники «Квалитет» свяжется с вами
              по указанному номеру телефона для подтверждения удобного времени
              визита.
            </p>
            <div className="pt-2 flex flex-wrap items-center gap-3">
              <button
                type="button"
                onClick={() => {
                  setSubmittedData(null);
                  setPatientName("");
                  setPhone("");
                  setComment("");
                }}
                className="inline-flex items-center justify-center rounded-lg border border-[#164E43]/30 bg-white px-4 py-2 text-xs font-medium text-[#164E43] hover:bg-[#164E43] hover:text-white transition"
              >
                Отправить ещё одну заявку
              </button>
              <a
                href="tel:+74994813208"
                className="inline-flex items-center gap-1.5 text-xs font-medium text-[#164E43] underline underline-offset-4"
              >
                <Phone className="h-3.5 w-3.5" />
                +7 (499) 481-32-08
              </a>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4" noValidate>
      {errorMessage && (
        <div
          role="alert"
          className="flex items-start gap-3 rounded-xl border border-[#B83232]/30 bg-[#B83232]/5 p-4 text-sm text-[#B83232]"
        >
          <AlertCircle className="h-5 w-5 shrink-0 mt-0.5" />
          <span>{errorMessage}</span>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <div>
          <label
            htmlFor="booking-name"
            className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[#525D59]"
          >
            Имя пациента <span className="text-[#B83232]">*</span>
          </label>
          <div className="relative">
            <User className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[#848E8A]" />
            <input
              id="booking-name"
              type="text"
              required
              value={patientName}
              onChange={(e) => setPatientName(e.target.value)}
              placeholder="Как к вам обращаться"
              className="h-12 w-full rounded-xl border border-[#E6E3DC] bg-white pl-10 pr-4 text-sm text-[#14221E] placeholder:text-[#848E8A] focus:border-[#164E43] focus:outline-none"
            />
          </div>
        </div>

        <div>
          <label
            htmlFor="booking-phone"
            className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[#525D59]"
          >
            Номер телефона <span className="text-[#B83232]">*</span>
          </label>
          <div className="relative">
            <Phone className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[#848E8A]" />
            <input
              id="booking-phone"
              type="tel"
              required
              value={phone}
              onChange={handlePhoneChange}
              placeholder="+7 (999) 000-00-00"
              className="h-12 w-full rounded-xl border border-[#E6E3DC] bg-white pl-10 pr-4 text-sm text-[#14221E] tabular-nums placeholder:text-[#848E8A] focus:border-[#164E43] focus:outline-none"
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <div>
          <label
            htmlFor="booking-direction"
            className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[#525D59]"
          >
            Направление стоматологии
          </label>
          <div className="relative">
            <Stethoscope className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[#848E8A]" />
            <select
              id="booking-direction"
              value={direction}
              onChange={(e) => {
                setDirection(e.target.value);
                setServiceTitle("");
              }}
              className="h-12 w-full rounded-xl border border-[#E6E3DC] bg-white pl-10 pr-4 text-sm text-[#14221E] focus:border-[#164E43] focus:outline-none"
            >
              <option value="">Первичная консультация / любое направление</option>
              {INITIAL_CATEGORIES.map((cat) => (
                <option key={cat.slug} value={cat.slug}>
                  {cat.title}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div>
          <label
            htmlFor="booking-service"
            className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[#525D59]"
          >
            Интересующая услуга
          </label>
          <select
            id="booking-service"
            value={serviceTitle}
            onChange={(e) => setServiceTitle(e.target.value)}
            className="h-12 w-full rounded-xl border border-[#E6E3DC] bg-white px-4 text-sm text-[#14221E] focus:border-[#164E43] focus:outline-none"
          >
            <option value="">Подобрать на приёме со специалистом</option>
            {filteredServices.map((srv) => (
              <option key={srv.slug} value={srv.title}>
                {srv.title} ({srv.priceDisplay})
              </option>
            ))}
          </select>
        </div>
      </div>

      {!compact && (
        <>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
            <div>
              <label
                htmlFor="booking-doctor"
                className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[#525D59]"
              >
                Предпочитаемый врач (необязательно)
              </label>
              {doctorsList.length > 0 ? (
                <select
                  id="booking-doctor"
                  value={preferredDoctor}
                  onChange={(e) => setPreferredDoctor(e.target.value)}
                  className="h-12 w-full rounded-xl border border-[#E6E3DC] bg-white px-3.5 text-sm text-[#14221E] focus:border-[#164E43] focus:outline-none"
                >
                  <option value="">Любой профильный специалист</option>
                  {doctorsList.map((doc) => (
                    <option key={doc.fullName} value={doc.fullName}>
                      {doc.fullName} ({doc.specialization})
                    </option>
                  ))}
                </select>
              ) : (
                <input
                  id="booking-doctor"
                  type="text"
                  value={preferredDoctor}
                  onChange={(e) => setPreferredDoctor(e.target.value)}
                  placeholder="Если знаете фамилию врача"
                  className="h-12 w-full rounded-xl border border-[#E6E3DC] bg-white px-3.5 text-sm text-[#14221E] placeholder:text-[#848E8A] focus:border-[#164E43] focus:outline-none"
                />
              )}
            </div>

            <div>
              <label
                htmlFor="booking-date"
                className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[#525D59]"
              >
                Желаемая дата (необязательно)
              </label>
              <div className="relative">
                <Calendar className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[#848E8A]" />
                <input
                  id="booking-date"
                  type="date"
                  value={desiredDate}
                  onChange={(e) => setDesiredDate(e.target.value)}
                  className="h-12 w-full rounded-xl border border-[#E6E3DC] bg-white pl-10 pr-3 text-sm text-[#14221E] focus:border-[#164E43] focus:outline-none"
                />
              </div>
            </div>

            <div>
              <label
                htmlFor="booking-time"
                className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[#525D59]"
              >
                Желаемое время (необязательно)
              </label>
              <div className="relative">
                <Clock className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[#848E8A]" />
                <select
                  id="booking-time"
                  value={desiredTime}
                  onChange={(e) => setDesiredTime(e.target.value)}
                  className="h-12 w-full rounded-xl border border-[#E6E3DC] bg-white pl-10 pr-3 text-sm text-[#14221E] focus:border-[#164E43] focus:outline-none"
                >
                  <option value="">Любое удобное время</option>
                  <option value="Утро (до 12:00)">Утро (до 12:00)</option>
                  <option value="День (12:00 – 17:00)">День (12:00 – 17:00)</option>
                  <option value="Вечер (после 17:00)">Вечер (после 17:00)</option>
                </select>
              </div>
            </div>
          </div>

          <div>
            <label
              htmlFor="booking-comment"
              className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[#525D59]"
            >
              Комментарий (необязательно)
            </label>
            <textarea
              id="booking-comment"
              rows={2}
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder="Укажите удобное время для звонка или краткий вопрос администратору (не указывайте подробные медицинские диагнозы)"
              className="w-full rounded-xl border border-[#E6E3DC] bg-white p-3.5 text-sm text-[#14221E] placeholder:text-[#848E8A] focus:border-[#164E43] focus:outline-none"
            />
          </div>
        </>
      )}

      <div className="flex items-start gap-3 pt-1">
        <input
          id="booking-consent"
          type="checkbox"
          checked={consentAccepted}
          onChange={(e) => setConsentAccepted(e.target.checked)}
          className="mt-1 h-4 w-4 rounded border-[#C9C4B9] text-[#164E43] focus:ring-[#164E43]"
        />
        <label
          htmlFor="booking-consent"
          className="text-xs leading-relaxed text-[#525D59]"
        >
          Я даю{" "}
          <Link
            href="/personal-data-consent"
            className="font-medium text-[#164E43] underline underline-offset-2 hover:text-[#0F3A31]"
          >
            согласие на обработку персональных данных
          </Link>{" "}
          и подтверждаю ознакомление с{" "}
          <Link
            href="/privacy-policy"
            className="font-medium text-[#164E43] underline underline-offset-2 hover:text-[#0F3A31]"
          >
            политикой конфиденциальности
          </Link>
          .
        </label>
      </div>

      <div className="flex flex-col gap-3 pt-2 sm:flex-row sm:items-center sm:justify-between">
        <button
          type="submit"
          disabled={isSubmitting}
          className="inline-flex h-12 items-center justify-center gap-2 rounded-xl bg-[#164E43] px-7 text-sm font-medium text-white shadow-sm transition hover:bg-[#0F3A31] disabled:opacity-60"
        >
          {isSubmitting ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              Отправка заявки...
            </>
          ) : (
            "Отправить заявку на приём"
          )}
        </button>

        <div className="flex items-center gap-2 text-xs text-[#525D59]">
          <ShieldCheck className="h-4 w-4 shrink-0 text-[#164E43]" />
          <span>Защищённая передача контактных данных</span>
        </div>
      </div>
    </form>
  );
}
